import{_ as t,a}from"./chunks/kefu-telegram.DsQ1DmYg.js";import{_ as s}from"./chunks/kefu-chat.CQaKJK-O.js";import{_ as o,o as i,c as r,a2 as n}from"./chunks/framework.DDY-poMm.js";const v=JSON.parse('{"title":"Customer Service","description":"","frontmatter":{},"headers":[],"relativePath":"guide/customer-service.md","filePath":"guide/customer-service.md","lastUpdated":1790683574000}'),l={name:"guide/customer-service.md"};function p(h,e,c,u,d,g){return i(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="customer-service" tabindex="-1">Customer Service <a class="header-anchor" href="#customer-service" aria-label="Permalink to &quot;Customer Service&quot;">​</a></h1><p>Users <strong>chat with support directly inside the app or mobile website</strong>, and agents reply from <strong>Telegram</strong> — no extra support software to install, and users do not need a Telegram account.</p><ul><li><strong>One conversation per user</strong>: each user automatically gets their own topic in the Telegram support group — no mix-ups, with a traceable history</li><li><strong>One conversation across both clients</strong>: users see the same chat history in the app and on the mobile website, and can continue on another device</li><li><strong>Text and images</strong>: users can send text and screenshots; agents&#39; text, emoji and images arrive in the app in real time</li><li><strong>Messages archived</strong>: all conversations are stored in the platform&#39;s own system and can be reviewed in the admin console at any time</li></ul><div class="tip custom-block"><p class="custom-block-title">Coverage</p><p>Currently the <strong>app and the mobile website (H5)</strong> are integrated. The PC website still uses its existing support window.</p></div><h2 id="what-users-see" tabindex="-1">What users see <a class="header-anchor" href="#what-users-see" aria-label="Permalink to &quot;What users see&quot;">​</a></h2><div style="display:flex;flex-wrap:wrap;gap:28px 20px;justify-content:center;margin:32px 0;"><figure style="margin:0;flex:0 0 240px;max-width:240px;"><img src="'+t+'" alt="Support entry on the app home page" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Entry</b><br>The headset icon at the top right of the home page; also reachable from &quot;Live chat&quot; on the &quot;Me&quot; page </figcaption></figure><figure style="margin:0;flex:0 0 240px;max-width:240px;"><img src="'+s+'" alt="Live chat page in the app" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Chat page</b><br>Agent on the left, user on the right; the button at the bottom left sends images </figcaption></figure></div><p>Users open an ordinary chat page; messages they send appear immediately in the agents&#39; Telegram. When an agent replies, the app page shows it <strong>without refreshing</strong>.</p><h2 id="what-agents-see" tabindex="-1">What agents see <a class="header-anchor" href="#what-agents-see" aria-label="Permalink to &quot;What agents see&quot;">​</a></h2><p>Agents only need a Telegram client (phone or desktop).</p><figure style="margin:32px auto;max-width:520px;"><img src="'+a+'" alt="A user topic in the Telegram support group" style="border-radius:10px;border:1px solid var(--vp-c-divider);width:100%;"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"> A user topic in the support group. The topic name is &quot;user ID + account&quot;; switch between users&#39; topics at the bottom </figcaption></figure><ul><li>When a user sends their <strong>first</strong> message, a <strong>new topic is created automatically</strong> in the support group, named &quot;user ID account&quot; (e.g. <code>391 test001</code>), so you can tell at a glance who it is</li><li>Agents <strong>reply directly in that topic</strong>, and the reply is delivered to that user&#39;s app</li><li>Agents can reply with text, emoji and images; voice messages and files are not forwarded to the app</li><li>Several agents can be in the group at once — whoever is free picks it up</li></ul><div class="warning custom-block"><p class="custom-block-title">Privacy protection</p><p>Before user messages are forwarded to Telegram, sensitive information such as ID numbers, bank card numbers and phone numbers is <strong>automatically masked</strong>; the platform&#39;s own system keeps the original text, viewable in the admin console when needed.</p></div><h2 id="reviewing-conversations-in-the-admin-console" tabindex="-1">Reviewing conversations in the admin console <a class="header-anchor" href="#reviewing-conversations-in-the-admin-console" aria-label="Permalink to &quot;Reviewing conversations in the admin console&quot;">​</a></h2><p>The &quot;<strong>Chat History</strong>&quot; page in the admin console lets you look up conversations by user ID and view the full history (time, sender, content). It is a <strong>read-only</strong> page for evidence and review — replies to users are still made in Telegram.</p><div class="tip custom-block"><p class="custom-block-title">Permission</p><p>This page must be granted separately to support / operations roles; accounts without the permission do not see the menu. For granting roles, see <a href="/CoinExchange/guide/admin-login">Admin Login &amp; Permissions</a>.</p></div><h2 id="how-to-enable-it" tabindex="-1">How to enable it <a class="header-anchor" href="#how-to-enable-it" aria-label="Permalink to &quot;How to enable it&quot;">​</a></h2><p>Enabling requires no engineering work; operators complete it in Telegram and the admin console. Follow the steps in order — <strong>none can be skipped</strong>.</p><h3 id="step-1-create-the-support-group-and-enable-topics" tabindex="-1">Step 1: Create the support group and enable Topics <a class="header-anchor" href="#step-1-create-the-support-group-and-enable-topics" aria-label="Permalink to &quot;Step 1: Create the support group and enable Topics&quot;">​</a></h3><p>Create a new Telegram group, upgrade it to a <strong>supergroup</strong> in the group settings, and turn on <strong>Topics</strong>.</p><div class="danger custom-block"><p class="custom-block-title">It must be a supergroup with Topics enabled</p><p>If you configure a private chat or an ordinary group, user messages cannot be delivered. This is the most common cause of a failed setup.</p></div><h3 id="step-2-create-a-dedicated-support-bot" tabindex="-1">Step 2: Create a dedicated support bot <a class="header-anchor" href="#step-2-create-a-dedicated-support-bot" aria-label="Permalink to &quot;Step 2: Create a dedicated support bot&quot;">​</a></h3><p>Create a <strong>new</strong> bot via Telegram&#39;s @BotFather and note its token.</p><div class="danger custom-block"><p class="custom-block-title">Do not reuse the deposit/withdrawal alert bot</p><p>If the platform already uses a Telegram bot for deposit/withdrawal alerts, support <strong>must use a separate bot</strong>. A bot can only be used by one system; sharing makes the two sides steal each other&#39;s messages and neither receives everything.</p></div><h3 id="step-3-add-the-bot-to-the-group-and-grant-permissions" tabindex="-1">Step 3: Add the bot to the group and grant permissions <a class="header-anchor" href="#step-3-add-the-bot-to-the-group-and-grant-permissions" aria-label="Permalink to &quot;Step 3: Add the bot to the group and grant permissions&quot;">​</a></h3><p>Add the bot to the support group, make it an <strong>administrator</strong>, and in its admin rights <strong>explicitly tick &quot;Manage Topics&quot;</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Making it admin is not enough</p><p>&quot;Manage Topics&quot; is a separate permission switch that is off by default. Without it, the bot cannot create topics for new users — the symptom is that nothing happens in the group after a user sends a message.</p></div><h3 id="step-4-fill-in-the-configuration-in-the-admin-console" tabindex="-1">Step 4: Fill in the configuration in the admin console <a class="header-anchor" href="#step-4-fill-in-the-configuration-in-the-admin-console" aria-label="Permalink to &quot;Step 4: Fill in the configuration in the admin console&quot;">​</a></h3><p>Go to &quot;<strong>Third-Party Configuration → Live chat</strong>&quot; in the admin console and fill in:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td>Enable live chat</td><td>Master switch. When on, every support entry in the app / H5 uses this system</td></tr><tr><td>Support bot token</td><td>The token from step 2</td></tr><tr><td>Support group ID</td><td>The ID of the group from step 1, usually starting with <code>-100</code></td></tr><tr><td>Callback URL</td><td>The address where the platform receives Telegram messages, provided by your technical team</td></tr><tr><td>Callback secret</td><td>A secret string used to verify where callbacks come from, provided by your technical team or set yourself</td></tr></tbody></table><p>On saving, the system registers the callback URL with Telegram automatically; only then do agents&#39; replies in the group reach the app.</p><div class="warning custom-block"><p class="custom-block-title">&quot;Saved successfully&quot; does not mean it is active</p><p>The system only registers the callback with Telegram when <strong>the switch is on and the token, callback URL and callback secret are all filled in</strong>. If any is missing, the page still says it saved successfully, but agents&#39; replies will not reach the app. When troubleshooting, check these four first.</p></div><h3 id="step-5-verify-with-a-test-account" tabindex="-1">Step 5: Verify with a test account <a class="header-anchor" href="#step-5-verify-with-a-test-account" aria-label="Permalink to &quot;Step 5: Verify with a test account&quot;">​</a></h3><ol><li>Open support in the app with a test account and send a message</li><li>A new topic named after that account should appear in the support group immediately, containing the message</li><li>Reply in the topic</li><li>The app&#39;s chat page should show the reply within a second or two, <strong>without refreshing</strong></li></ol><p>Once all four steps pass, it is ready for use.</p><h2 id="turning-it-off-or-rolling-back" tabindex="-1">Turning it off or rolling back <a class="header-anchor" href="#turning-it-off-or-rolling-back" aria-label="Permalink to &quot;Turning it off or rolling back&quot;">​</a></h2><p>Just turn off the &quot;Enable live chat&quot; switch. Once off:</p><ul><li>The support entries in the app and H5 <strong>fall back to the original external-link support</strong> (that configuration is still kept under &quot;Support Settings&quot; in the admin console and was not deleted)</li><li>Existing conversation records are not lost and are available again once the switch is turned back on</li></ul><div class="tip custom-block"><p class="custom-block-title">After changing the configuration</p><p>As with other admin settings, app users must <strong>fully quit and reopen the app</strong> to receive the new switch state; the mobile website just needs a refresh.</p></div><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ {#faq}&quot;">​</a></h2><h3 id="a-user-sent-a-message-but-nothing-appears-in-the-support-group" tabindex="-1">A user sent a message, but nothing appears in the support group? <a class="header-anchor" href="#a-user-sent-a-message-but-nothing-appears-in-the-support-group" aria-label="Permalink to &quot;A user sent a message, but nothing appears in the support group?&quot;">​</a></h3><p>Check in order:</p><ol><li>Is &quot;Enable live chat&quot; turned on in the admin console?</li><li>Is the &quot;Support group ID&quot; a <strong>supergroup with Topics enabled</strong>? Using a private chat or ordinary group is the most common mistake</li><li>Is the bot in the group, is it an administrator, and <strong>is &quot;Manage Topics&quot; explicitly ticked</strong>?</li></ol><h3 id="the-user-s-message-reaches-the-group-but-agents-replies-don-t-reach-the-app" tabindex="-1">The user&#39;s message reaches the group, but agents&#39; replies don&#39;t reach the app? <a class="header-anchor" href="#the-user-s-message-reaches-the-group-but-agents-replies-don-t-reach-the-app" aria-label="Permalink to &quot;The user&#39;s message reaches the group, but agents&#39; replies don&#39;t reach the app?&quot;">​</a></h3><p>Messages get in but don&#39;t come back, so the problem is in the callback:</p><ol><li>Are both &quot;Callback URL&quot; and &quot;Callback secret&quot; filled in? (If either is missing, the system does not register the callback)</li><li>Did you <strong>save again</strong> after filling them in? (Registration happens on save)</li><li>Is the agent replying in <strong>the user&#39;s topic</strong>, rather than in the group&#39;s &quot;General&quot;?</li></ol><h3 id="an-agent-sent-a-voice-message-file-but-the-user-says-they-didn-t-get-it" tabindex="-1">An agent sent a voice message / file, but the user says they didn&#39;t get it? <a class="header-anchor" href="#an-agent-sent-a-voice-message-file-but-the-user-says-they-didn-t-get-it" aria-label="Permalink to &quot;An agent sent a voice message / file, but the user says they didn&#39;t get it?&quot;">​</a></h3><p>Only <strong>text, emoji and images</strong> are forwarded for now. Voice messages and files are not delivered to the app; please use text or screenshots instead.</p><h3 id="can-one-user-end-up-with-several-topics" tabindex="-1">Can one user end up with several topics? <a class="header-anchor" href="#can-one-user-end-up-with-several-topics" aria-label="Permalink to &quot;Can one user end up with several topics?&quot;">​</a></h3><p>No. Each user has exactly one topic, whether they start from the app or the mobile website.</p>',49)])])}const y=o(l,[["render",p]]);export{v as __pageData,y as default};
